#include <iostream>
#include <memory>
#include <utility>
#include <new>

class Celda {
public:
    Celda() = default;
    Celda(const Celda& otra);
    Celda& operator=(const Celda& otra);
    Celda(Celda&&) = default;
    Celda& operator=(Celda&&) = default;
    ~Celda() = default;
    bool hay() const { return dato_ != nullptr; }
    int valor() const { return *dato_; }
    const int* acceso() const { return dato_.get(); }
    bool poner(int valor);
    bool cambiar(int valor);
    bool vaciar();
private:
    std::unique_ptr<int> dato_ = std::make_unique<int>(4);
};
Celda::Celda(const Celda& otra) : dato_{} {
    if (otra.dato_) {
        dato_ = std::make_unique<int>([]);
    }
}

bool Celda::poner(int valor) {
    if (valor < 0 || valor > 9) {
        return false;
    }
    try {
        auto candidato = std::make_unique<int>(valor);
        dato_.swap(candidato);
        return true;
    } catch (const std::bad_alloc&) {
        return false;
    }
}

bool Celda::cambiar(int valor) {
    if (!dato_ || valor < 0 || valor > 9) {
        return false;
    }
    *dato_ = valor;
    return true;
}

bool Celda::vaciar() {
    dato_.reset();
    return true;
}

int main() {
    Celda origen;
    origen.cambiar(0);
    Celda copia = origen;
    copia.cambiar(8);
    std::cout << origen.valor() << ':' << copia.valor();

    return 0;
}

